import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    static class Line {
        long y1, y2;

        Line(long y1, long y2) {
            this.y1 = y1;
            this.y2 = y2;
        }
    }

    static class Fenwick {
        int[] tree;

        Fenwick(int n) {
            tree = new int[n + 1];
        }

        void add(int index, int value) {
            for (int i = index; i < tree.length; i += i & -i) {
                tree[i] += value;
            }
        }

        int sum(int index) {
            int result = 0;
            for (int i = index; i > 0; i -= i & -i) {
                result += tree[i];
            }
            return result;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = (int) fs.nextLong();
        long x1 = fs.nextLong();
        long x2 = fs.nextLong();

        Line[] lines = new Line[n];
        long[] y2Values = new long[n];

        for (int i = 0; i < n; i++) {
            long a = fs.nextLong();
            long b = fs.nextLong();
            long y1 = a * x1 + b;
            long y2 = a * x2 + b;
            lines[i] = new Line(y1, y2);
            y2Values[i] = y2;
        }

        Arrays.sort(lines, Comparator.comparingLong(line -> line.y1));
        Arrays.sort(y2Values);

        long[] unique = new long[n];
        int uniqueCount = 0;
        for (long value : y2Values) {
            if (uniqueCount == 0 || unique[uniqueCount - 1] != value) {
                unique[uniqueCount++] = value;
            }
        }

        Fenwick fenwick = new Fenwick(uniqueCount);
        long answer = 0;
        int processed = 0;

        for (int start = 0; start < n; ) {
            int end = start + 1;
            while (end < n && lines[end].y1 == lines[start].y1) {
                end++;
            }

            int groupSize = end - start;
            answer += (long) groupSize * (groupSize - 1) / 2;

            for (int i = start; i < end; i++) {
                int rank = Arrays.binarySearch(unique, 0, uniqueCount, lines[i].y2) + 1;
                answer += processed - fenwick.sum(rank - 1);
            }

            for (int i = start; i < end; i++) {
                int rank = Arrays.binarySearch(unique, 0, uniqueCount, lines[i].y2) + 1;
                fenwick.add(rank, 1);
            }
            processed += groupSize;
            start = end;
        }

        System.out.println(answer);
    }
}
